"""
app.py - Painel Detesaun Fraude Tempu-Reál (Streamlit) - versaun lian Tetun
==========================================================================

    streamlit run dashboard/app.py          # http://localhost:8501

Lee rezultadu husi PostgreSQL (hakerek husi Spark Streaming) no atualiza an rasik kada segundu balun.
"""
from __future__ import annotations

import base64
import json
import sys
from datetime import datetime
from pathlib import Path

import pandas as pd
import plotly.express as px
import streamlit as st

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import config  # noqa: E402
from storage import db  # noqa: E402

st.set_page_config(page_title="Real-Time Fraud Detection", page_icon="🛡️", layout="wide")
DEC_COLOR = {"APPROVE": "#1f9d55", "REVIEW": "#f0a020", "BLOCK": "#d63333"}
DEC_LABEL = {"APPROVE": "SEGURU - APROVA", "REVIEW": "SUSPEITU - REVIZAUN", "BLOCK": "FRAUDE - BLOKEIA"}
SRC_LABEL = {"bank": "Transasaun Bank (bank_transactions_data_2)", "banksim": "Pagamentu Bank (BankSim)",
             "card": "Transasaun Kartaun Kréditu (creditcard.csv)"}
# kódigu razaun (husi Spark) -> Tetun; troka de'it iha painel, dadus iha PostgreSQL la muda
REASON_TET = [("POLA_TRANSAKSI_KARTU_MIRIP_FRAUD(model)", "PADRAUN_KARTAUN_HANESAN_FRAUDE(modelu)"),
              ("JUMLAH_SANGAT_KECIL_DIBANDING_KEBIASAAN", "MONTANTE_KIIK_LIU_BAIBAIN"),
              ("JUMLAH_JAUH_DI_ATAS_KEBIASAAN", "MONTANTE_AS_LIU_BAIBAIN"),
              ("JUMLAH_>3x_RATA2_PELANGGAN", "MONTANTE_>3x_MÉDIA_KLIENTE"),
              ("JUMLAH_>3x_RATA2_AKUN", "MONTANTE_>3x_MÉDIA_KONTA"),
              ("PERANGKAT_DIPAKAI_BANYAK_AKUN", "APARELLU_UZA_HUSI_KONTA_BARAK"),
              ("IP_DIPAKAI_BANYAK_AKUN", "IP_UZA_HUSI_KONTA_BARAK"),
              ("LOKASI_BARU_UNTUK_AKUN", "FATIN_FOUN_BA_KONTA"),
              ("NILAI_FITUR_PCA_EKSTREM", "VALÓR_PCA_EKSTREMU"),
              ("PELANGGAN_TANPA_RIWAYAT", "KLIENTE_LA_IHA_ISTÓRIA"),
              ("AKUN_TANPA_RIWAYAT", "KONTA_LA_IHA_ISTÓRIA"),
              ("KATEGORI_BERISIKO_", "KATEGORIA_RISKU_"),
              ("JUMLAH_BESAR", "MONTANTE_BOOT"),
              ("model belum dilatih", "modelu seidauk treina")]
REJECT_TET = {"MALFORMED_JSON": "JSON_AT", "MISSING_EVENT_ID": "ID_EVENTU_LA_IHA", "UNKNOWN_SOURCE": "FONTE_LA_KOÑESIDU",
              "MISSING_AMOUNT": "MONTANTE_LA_IHA", "INVALID_AMOUNT": "MONTANTE_LA_VÁLIDU",
              "INVALID_EVENT_TIME": "TEMPU_EVENTU_LA_VÁLIDU"}


def tet(reasons) -> str:
    """Tradús razaun ida-idak ba Tetun."""
    if not isinstance(reasons, str):
        return ""
    for a, b in REASON_TET:
        reasons = reasons.replace(a, b)
    return reasons
st.markdown("""<style>
.block-container{padding-top:1.1rem}
.kpi{border:1px solid #e6e6e6;border-radius:10px;padding:12px 14px;background:#fbfbfb}
.kpi .l{font-size:.72rem;color:#555;text-transform:uppercase;letter-spacing:.05em}
.kpi .v{font-size:1.6rem;font-weight:700}
.alert{border-left:6px solid #d63333;background:#fdeeee;padding:8px 12px;border-radius:6px;margin-bottom:6px;font-size:.86rem;color:#222}
.review{border-left:6px solid #f0a020;background:#fff6e5}
</style>""", unsafe_allow_html=True)


def kpi(col, label, value, color="#111"):
    col.markdown(f"<div class='kpi'><div class='l'>{label}</div><div class='v' style='color:{color}'>{value}</div></div>",
                 unsafe_allow_html=True)


def q(sql, params=None):
    try:
        return db.query(sql, params)
    except Exception as e:  # noqa: BLE001
        st.error(f"La bele lee PostgreSQL ({config.PG_HOST}:{config.PG_PORT}): {e}")
        st.stop()


# ---------------------------------------------------------------- menu sorin
st.sidebar.markdown("## 🛡️ Detesaun Fraude")
page = st.sidebar.radio("Pájina", ["📊 Painel Tempu-Reál", "🧠 Modelu no Avaliasaun", "🏗️ Arkitetura no Dadus"])
st.sidebar.markdown("---")


# ================================================================ PAINEL
def live():
    refresh = st.sidebar.slider("Atualiza automátiku (segundu)", 0, 30, 3, help="0 = la atualiza")
    win = st.sidebar.selectbox("Períodu tempu", ["Dadus hotu", "Minutu 5 ikus", "Oras 1 ikus"])
    srcs = st.sidebar.multiselect("Fonte dadus", list(config.SOURCES), default=list(config.SOURCES),
                                  format_func=lambda s: SRC_LABEL[s])
    st.sidebar.caption("Desizaun: SEGURU-APROVA · SUSPEITU-REVIZAUN · FRAUDE-BLOKEIA. Fonte bank la iha label "
                       "-> maximu REVIZAUN.")

    @st.fragment(run_every=refresh or None)
    def body():
        cond, params = ["source = ANY(%(s)s)"], {"s": srcs or ["-"]}
        if win != "Dadus hotu":
            cond.append("processed_at >= (now() AT TIME ZONE 'utc') - %(iv)s::interval")
            params["iv"] = "5 minutes" if "5" in win else "1 hour"
        where = " AND ".join(cond)
        k = q(f"""SELECT COUNT(*) n, COALESCE(SUM(amount),0) total, SUM((decision='BLOCK')::int) blk,
                         SUM((decision='REVIEW')::int) rev, AVG(latency_ms) lat, MAX(processed_at) last
                  FROM v_scored WHERE {where}""", params).iloc[0]
        h1, h2 = st.columns([3, 1])
        h1.markdown("## 🛡️ Sistema Detesaun Fraude Tempu-Reál")
        h1.caption("CSV → Apache Kafka → Spark Structured Streaming → Spark MLlib → PostgreSQL → Streamlit")
        alive = q("SELECT MAX(created_at) t FROM batch_metrics").t.iloc[0]
        status = "🟢 Spark ativu" if alive is not None and (datetime.utcnow() - alive).total_seconds() < 30 \
            else "⚪ Spark la haruka dadus"
        h2.metric("Atualizasaun ikus", datetime.now().strftime("%H:%M:%S"), status, delta_color="off")
        n = int(k.n or 0)
        if n == 0:
            st.info("Seidauk iha transasaun. Halai Kafka, Spark Streaming no producer (haree README).")
            return
        c = st.columns(6)
        kpi(c[0], "Totál transasaun", f"{n:,}")
        tot = float(k.total)
        kpi(c[1], "Valór totál (moeda mistura)", f"{tot / 1e6:,.1f} millaun" if tot >= 1e6 else f"{tot:,.0f}")
        kpi(c[2], "FRAUDE - BLOKEIA", f"{int(k.blk or 0):,}", DEC_COLOR["BLOCK"])
        kpi(c[3], "SUSPEITU - REVIZAUN", f"{int(k.rev or 0):,}", DEC_COLOR["REVIEW"])
        kpi(c[4], "Persentajen ho risku", f"{100 * (int(k.blk or 0) + int(k.rev or 0)) / n:.2f}%")
        kpi(c[5], "Laténsia médiu", f"{float(k.lat or 0) / 1000:.2f} s")

        last_block = q(f"""SELECT a.*, t.event_time FROM alerts a JOIN transactions t USING(event_id)
                           WHERE a.decision='BLOCK' AND a.source = ANY(%(s)s) ORDER BY a.alert_id DESC LIMIT 1""",
                       {"s": srcs or ["-"]})
        if not last_block.empty:
            r = last_block.iloc[0]
            st.error(f"🚨 **ALERTA SEDU - FRAUDE DETETA ONA** · {r.event_id} · {SRC_LABEL.get(r.source, r.source)} · "
                     f"montante {float(r.amount):,.2f} · skór {r.risk_score:.3f} · {tet(r.reasons)}")

        a, b = st.columns([1, 2])
        with a:
            st.markdown("**Alerta foun liu**")
            al = q(f"SELECT * FROM alerts WHERE source = ANY(%(s)s) ORDER BY alert_id DESC LIMIT 8", {"s": srcs or ["-"]})
            for r in al.itertuples():
                cls = "alert" if r.decision == "BLOCK" else "alert review"
                st.markdown(f"<div class='{cls}'><b>{DEC_LABEL[r.decision]}</b> · {r.event_id}<br>"
                            f"{SRC_LABEL.get(r.source, r.source)} · konta {r.account_id if isinstance(r.account_id, str) else '-'} · "
                            f"<b>{float(r.amount):,.2f}</b> · skór {r.risk_score:.3f}<br>"
                            f"<small>{tet(r.reasons)}</small></div>", unsafe_allow_html=True)
            if al.empty:
                st.success("Seidauk iha alerta.")
        with b:
            st.markdown("**Transasaun tempu-reál (foun liu iha leten)**")
            t = q(f"""SELECT event_id, source, account_id, amount, tx_type, channel, location, risk_score, decision,
                             label, reasons, round(latency_ms) latency_ms FROM v_scored WHERE {where}
                      ORDER BY processed_at DESC, event_id LIMIT 150""", params)
            t["decision"] = t.decision.map(DEC_LABEL)
            t["label"] = t.label.map({1: "fraude", 0: "normál"}).fillna("-")
            t["reasons"] = t.reasons.map(tet)
            t = t.rename(columns={"event_id": "id_eventu", "source": "fonte", "account_id": "konta",
                                  "amount": "montante", "tx_type": "tipu", "channel": "kanál", "location": "fatin",
                                  "risk_score": "skór_risku", "decision": "desizaun", "reasons": "razaun",
                                  "latency_ms": "laténsia_ms"})

            def color(row):
                bg = {DEC_LABEL["BLOCK"]: "#fbe0e0", DEC_LABEL["REVIEW"]: "#fff2d6"}.get(row["desizaun"], "")
                return [f"background-color:{bg};color:#111" if bg else ""] * len(row)
            st.dataframe(t.style.apply(color, axis=1).format({"skór_risku": "{:.3f}", "montante": "{:,.2f}"}),
                         height=420, width="stretch", hide_index=True)

        st.markdown("### Analítika")
        r1, r2 = st.columns(2)
        ag = q("""SELECT window_start, source, tx_count, total_amount, known_fraud FROM agg_minute
                  WHERE source = ANY(%(s)s) ORDER BY window_start""", {"s": srcs or ["-"]})
        if not ag.empty:
            ag["fonte"] = ag.source.map(SRC_LABEL)
            r1.plotly_chart(px.bar(ag, x="window_start", y="tx_count", color="fonte",
                                   labels={"window_start": "minutu", "tx_count": "transasaun"},
                                   title="Transasaun kada minutu (agregasaun Spark Streaming)", height=330),
                            width="stretch")
        d = q(f"SELECT source, decision, COUNT(*) n FROM v_scored WHERE {where} GROUP BY 1,2", params)
        d["fonte"], d["desizaun"] = d.source.map(SRC_LABEL), d.decision.map(DEC_LABEL)
        r2.plotly_chart(px.bar(d, x="fonte", y="n", color="desizaun", barmode="stack", log_y=True,
                               labels={"n": "transasaun"},
                               color_discrete_map={DEC_LABEL[k]: v for k, v in DEC_COLOR.items()},
                               title="Desizaun kada fonte (eskala log)", height=330), width="stretch")
        r3, r4 = st.columns(2)
        sc = q(f"SELECT source, risk_score, decision FROM v_scored WHERE {where} ORDER BY processed_at DESC LIMIT 20000",
               params)
        sc["fonte"] = sc.source.map(SRC_LABEL)
        r3.plotly_chart(px.histogram(sc, x="risk_score", color="fonte", labels={"risk_score": "skór risku", "count": "totál"}, nbins=50, log_y=True, barmode="overlay",
                                     opacity=.75, title="Distribuisaun skór risku (0..1)", height=330),
                        width="stretch")
        am = q(f"SELECT source, amount::float amount, decision FROM v_scored WHERE {where} AND amount > 0 "
               f"ORDER BY processed_at DESC LIMIT 20000", params)
        am["desizaun"] = am.decision.map(DEC_LABEL)
        r4.plotly_chart(px.box(am, x="desizaun", y="amount", color="desizaun", labels={"amount": "montante"}, log_y=True, points=False,
                               color_discrete_map={DEC_LABEL[k]: v for k, v in DEC_COLOR.items()},
                               title="Montante transasaun kada desizaun (log)", height=330), width="stretch")

        st.markdown("### Avaliasaun direta (fonte ho label: kartaun kréditu no BankSim)")
        ev = q(f"""SELECT source,
                     SUM((decision='BLOCK' AND label=1)::int) tp_blk, SUM((decision='BLOCK' AND label=0)::int) fp_blk,
                     SUM((decision<>'BLOCK' AND label=1)::int) fn_blk,
                     SUM((decision<>'APPROVE' AND label=1)::int) tp_any, SUM((decision<>'APPROVE' AND label=0)::int) fp_any,
                     SUM((decision='APPROVE' AND label=1)::int) fn_any, SUM(label) fraud, COUNT(*) n
                   FROM v_scored WHERE {where} AND label IS NOT NULL GROUP BY source""", params)
        if not ev.empty:
            rows = []
            for r in ev.itertuples():
                for nm, tp, fp, fn in (("BLOKEIA de'it", r.tp_blk, r.fp_blk, r.fn_blk),
                                       ("REVIZAUN + BLOKEIA", r.tp_any, r.fp_any, r.fn_any)):
                    rows.append({"fonte": SRC_LABEL[r.source], "konta hanesan fraude": nm, "transasaun": r.n,
                                 "fraude loos": r.fraud, "deteta (TP)": tp, "alarme falsu (FP)": fp,
                                 "la deteta (FN)": fn, "precision": round(tp / (tp + fp), 3) if tp + fp else None,
                                 "recall": round(tp / (tp + fn), 3) if tp + fn else None})
            st.dataframe(pd.DataFrame(rows), hide_index=True, width="stretch")
            st.caption("Label loos uza de'it ba avaliasaun; modelu la haree label durante streaming.")

        st.markdown("### Saúde pipeline")
        p1, p2 = st.columns([2, 1])
        p1.dataframe(q("""SELECT batch_id, rows_in liña_tama, rows_valid liña_válidu, rows_rejected liña_rejeita,
                                 rows_duplicate liña_duplikadu, n_review revizaun, n_block blokeia,
                                 processing_ms prosesa_ms, avg_latency_ms laténsia_médiu_ms, created_at tempu
                          FROM batch_metrics ORDER BY id DESC LIMIT 10"""),
                     hide_index=True, width="stretch")
        rj = q("SELECT reason, COUNT(*) n FROM rejected_records GROUP BY reason ORDER BY n DESC")
        rj["reason"] = rj.reason.map(lambda x: REJECT_TET.get(x, x))
        rj = rj.rename(columns={"reason": "razaun", "n": "totál"})
        p2.markdown("**Dadus ne'ebé rejeita durante limpeza**")
        p2.dataframe(rj, hide_index=True, width="stretch")

    body()


# ================================================================ MODELU
ALGO_TET = {"bank": "KMeans clustering (Spark MLlib) + distánsia ba sentru kluster",
            "banksim": "GBTClassifier (Spark MLlib)", "card": "GBTClassifier (Spark MLlib)"}
ROW_TET = {"BLOCK_only (prob >= ambang blokir)": "BLOKEIA de'it (prob >= limite blokeia)",
           "REVIEW_or_BLOCK (prob >= ambang tinjau)": "REVIZAUN ka BLOKEIA (prob >= limite revizaun)"}


def models():
    st.markdown("## 🧠 Modelu Spark MLlib no rezultadu avaliasaun")
    f = config.RESULTS_DIR / "model_evaluation.json"
    if not f.exists():
        st.warning("Seidauk iha rezultadu. Halai: python spark_jobs/train_models.py")
        return
    R = json.loads(f.read_text(encoding="utf-8"))
    st.caption("REZULTADU FAKTUÁL - kalkula husi ezekusaun loos iha dadus teste (fahe tuir tempu)")
    for src in ("banksim", "card", "bank"):
        m = R.get(src)
        if not m:
            continue
        st.markdown(f"### {SRC_LABEL[src]} — {ALGO_TET.get(src, m.get('algorithm', ''))}")
        if "skipped" in m:
            st.warning(m["skipped"]); continue
        if src == "bank":
            c = st.columns(4)
            c[0].metric("Liña", f"{m['rows']:,}"); c[1].metric("Kluster (k)", m["k_selected"])
            c[2].metric("Marka REVIZAUN", f"{m['flagged_review_rows']} ({m['flagged_pct']}%)")
            c[3].metric("Silhouette di'ak liu", max(m["silhouette_by_k"].values()))
            st.info("Dataset ne'e la iha label fraude. Rezultadu mak ANOMALIA (transasaun ne'ebé la normál liu), "
                    "la'ós fraude ne'ebé prova ona; tanba ne'e desizaun maximu = REVIZAUN, nunka BLOKEIA automátiku.")
            ta = pd.DataFrame(m["top_anomalies"])
            ta["reasons"] = ta.reasons.map(tet)
            st.dataframe(ta.rename(columns={"account_id": "konta", "amount": "montante", "channel": "kanál",
                                            "location": "fatin", "distance": "distánsia", "reasons": "razaun"}),
                         hide_index=True, width="stretch")
            continue
        t = m["test"]
        c = st.columns(5)
        c[0].metric("Dadus teste", f"{t['rows']:,}"); c[1].metric("Fraude iha dadus teste", f"{t['fraud']:,}")
        c[2].metric("ROC-AUC", t["roc_auc"]); c[3].metric("PR-AUC", t["pr_auc"])
        c[4].metric("Limite BLOKEIA / REVIZAUN", f"{m['thresholds']['block']:.3f} / {m['thresholds']['review']:.3f}")
        st.dataframe(pd.DataFrame({ROW_TET.get(k, k): v for k, v in t.items() if isinstance(v, dict)}).T, width="stretch")
        if "caution" in m:
            st.warning(m["caution"])
        if "ablation_without_balance_features" in m:
            ab = m["ablation_without_balance_features"]["test"]
            st.markdown(f"La ho feature saldu: ROC-AUC **{ab['roc_auc']}**, PR-AUC **{ab['pr_auc']}**")
            st.dataframe(pd.DataFrame({ROW_TET.get(k, k): v for k, v in ab.items() if isinstance(v, dict)}).T, width="stretch")
        if "baseline_rule_category_or_amount" in m:
            b = m["baseline_rule_category_or_amount"]
            st.caption(f"Komparasaun ho regra simples ({b['rule'].replace('kategori', 'kategoria').replace('ATAU nominal', 'KA montante')}): precision {b['precision']}, recall {b['recall']}, "
                       f"F1 {b['f1']}")
        if "comparison" in m:
            st.dataframe(pd.DataFrame({k.replace("pembanding", "komparasaun"): {"roc_auc": v["test"]["roc_auc"], "pr_auc": v["test"]["pr_auc"],
                                           **{f"BLOKEIA {kk}": vv for kk, vv in
                                              v["test"]["BLOCK_only (prob >= ambang blokir)"].items()
                                              if kk in ("precision", "recall", "f1")}}
                                       for k, v in m["comparison"].items()}).T, width="stretch")


# ================================================================ ARKITETURA
def arch():
    st.markdown("## 🏗️ Arkitetura sistema no fonte dadus")
    st.image(base64.b64decode(ARCH_PNG_B64))
    rows = []
    for s, v in config.SOURCES.items():
        p = config.find_source_file(s)
        rows.append({"id": s, "naran iha painel": SRC_LABEL[s], "arkivu": p.name if p else "(seidauk iha data/raw)",
                     "label fraude": "sin" if v["has_label"] else "lae"})
    st.dataframe(pd.DataFrame(rows), hide_index=True, width="stretch")



